'use client';
import React,{useState} from 'react';
import type {State,RecordRow as R} from '@/lib/erp-primitives';
import {day} from '@/lib/erp-primitives';
import {periodBounds} from '@/lib/hagadol-os';
import {eosSnapshot,l10Agenda} from '@/lib/leadership';
import L10Meeting from './erp-l10';
import {StartL10} from './erp-l10-lifecycle';
import {RockOverview,RockProgress} from './erp-leadership';
const fmt=(n:number)=>new Intl.NumberFormat('en-UG',{maximumFractionDigits:1}).format(n||0);
const names=['L10 meetings','Overview','Rocks','Scorecard','To dos','Issues'];
const issueStages=['Open','Discussing','Solved','Archived'];
export default function EOS({state,company,open,create,act,busy,initial={},activeTab,onTabChange,onDirtyChange,refresh}:{refresh?:()=>Promise<void>;onDirtyChange?:(v:boolean)=>void;activeTab?:string;onTabChange?:(t:string)=>void;initial?:{tab?:string;selectedIssue?:string;selectedMeeting?:string};state:State;company:string;open:(type:string,r?:R)=>void;create:(type:string,seed?:any)=>void;act:(x:any)=>Promise<unknown>;busy:boolean}){
const [localTab,setLocalTab]=useState(initial.tab||'L10 meetings'),[anchor,setAnchor]=useState(day()),[period,setPeriod]=useState('Week'),[taskFilter,setTaskFilter]=useState('Open'),[issueFilter,setIssueFilter]=useState('Open'),[selectedIssue,setSelectedIssue]=useState(initial.selectedIssue||''),[selectedMeeting,setSelectedMeeting]=useState(initial.selectedMeeting||'');
const [starting,setStarting]=useState(false);
const [meetingDirty,setMeetingDirty]=useState(false);function updateDirty(v:boolean){setMeetingDirty(v);onDirtyChange?.(v)}
const tab=activeTab||localTab;function setTab(t:string){if(meetingDirty&&!window.confirm('Discard unsaved meeting notes?'))return;updateDirty(false);setLocalTab(t);onTabChange?.(t);}
const rs=state.records.filter(r=>company==='Group'||r.company===company),s=eosSnapshot(state.records,company,day()),bounds=periodBounds(period,anchor),quarter=periodBounds('Quarter',anchor),metrics=rs.filter(r=>r.type==='scorecard'&&r.period===period&&r.periodStart===bounds.start&&r.date===bounds.end),rocks=rs.filter(r=>r.type==='rock'&&r.periodStart<=quarter.end&&r.date>=quarter.start),todos=s.todos.filter(r=>taskFilter==='All'||(taskFilter==='Done'?r.status==='Done':r.status!=='Done')).sort((a,b)=>a.due.localeCompare(b.due)),issues=(issueFilter==='Open'?s.openIssues:s.issues.filter(r=>issueFilter==='All'||r.status===issueFilter)),issue=s.issues.find(r=>r.id===selectedIssue),meeting=s.meetings.find(r=>r.id===selectedMeeting)||s.meetings.find(r=>r.status==='In progress')||s.meetings.find(r=>r.status==='Planned')||s.meetings[0];
const seedCompany=company==='Group'?'Hagadol':company;
const newRock=()=>create('rock',{company:seedCompany,period:'Quarter',periodStart:quarter.start,date:quarter.end});
const newMetric=()=>create('scorecard',{company:seedCompany,period,periodStart:bounds.start,date:bounds.end,unit:''});
const newTodo=(seed:any={})=>create('task',{company:seedCompany,eos:true,due:new Date(Date.parse(day()+'T12:00:00Z')+7*86400000).toISOString().slice(0,10),...seed});
const newIssue=(seed:any={})=>create('eos_issue',{company:seedCompany,...seed});
const status=(r:R,values:string[])=><label className="eosstatus">Status<select aria-label={'Status for '+r.name} disabled={busy} value={r.status} onChange={e=>act({action:'stage',id:r.id,status:e.target.value})}>{values.map(v=><option key={v}>{v}</option>)}</select></label>;
const meetingMode=tab==='L10 meetings'&&meeting?.status==='In progress';
const moduleMenu=<nav className="eostabs" aria-label="EOS modules">{names.map(n=><button key={n} className={tab===n?'primary':'secondary'} aria-pressed={tab===n} onClick={()=>setTab(n)}>{n}</button>)}</nav>;
return <div className="eosworkspace">{meetingMode?<div className="eosmeetingmode"><div><strong>L10 meeting mode</strong><span>{meeting.company} · {meeting.agendaStep||'Segue'}</span></div><details><summary>Preparation views</summary>{moduleMenu}</details></div>:moduleMenu}
<details className="quiethelp"><summary>About EOS records</summary><p>{company==='Group'?'Group oversight shows both companies. Each meeting, issue and action belongs to WMK or Hagadol.':'EOS records belong to '+company+'.'} Scorecards can link to finance, CRM, projects and recorded marketing metrics. Rock progress remains a management assessment.</p></details>
{tab==='Overview'&&<><div className="eosnumbers"><div><span>Open EOS To dos</span><strong>{s.todos.filter(r=>r.status!=='Done').length}</strong></div><div><span>Overdue To dos</span><strong>{s.overdue.length}</strong></div><div><span>Open issues</span><strong>{s.openIssues.length}</strong></div><div><span>Completed L10 meetings</span><strong>{s.meetings.filter(r=>r.status==='Completed').length}</strong></div></div><div className="sectiontoolbar"><button className="primary" onClick={()=>{setStarting(true);setTab('L10 meetings')}}>Start L10 meeting</button><button className="secondary" onClick={newRock}>Add quarterly Rock</button><button className="secondary" onClick={()=>newIssue()}>Add issue</button><button className="secondary" onClick={()=>newTodo()}>Add To do</button></div><h2>{quarter.label} Rocks</h2><RockOverview rocks={rocks}/><div className="eoscolumns"><section><h2>Actions needing attention</h2>{s.overdue.slice(0,6).map(r=><button className="eoslistlink" key={r.id} onClick={()=>open('task',r)}><strong>{r.name}</strong><span>{r.company} · {r.owner} · Due {r.due}</span></button>)}{!s.overdue.length&&<p className="empty">No overdue EOS To dos.</p>}</section><section><h2>Priority issues</h2>{s.openIssues.slice(0,6).map(r=><button className="eoslistlink" key={r.id} onClick={()=>{setTab('Issues');setSelectedIssue(r.id)}}><strong>{r.name}</strong><span>{r.company} · {r.priority} · {r.owner}</span></button>)}{!s.openIssues.length&&<p className="empty">No open issues recorded.</p>}</section></div></>}
{['Scorecard','Rocks'].includes(tab)&&<div className="commandfilters">{tab==='Scorecard'&&<label>Reporting period<select value={period} onChange={e=>setPeriod(e.target.value)}>{['Week','Month','Quarter'].map(v=><option key={v}>{v}</option>)}</select></label>}<label>Date within period<input type="date" value={anchor} onChange={e=>e.target.value&&setAnchor(e.target.value)}/></label><strong>{tab==='Rocks'?quarter.label:bounds.label}</strong><button className="primary" onClick={tab==='Rocks'?newRock:newMetric}>Add {tab==='Rocks'?'Rock':'metric'}</button></div>}
{tab==='Scorecard'&&<><p className="notice">Weekly periods run Monday to Sunday. Choose a manual actual or a linked source and assign one metric owner. Linked actuals calculate through today or the period end, whichever comes first.</p><div className="eosmetricgrid">{metrics.map(r=>{const pending=r.metricPending===true||r.actual===null;const good=r.direction==='At most'?r.actual<=r.targetValue:r.actual>=r.targetValue;return <article className="eosmetric" key={r.id}><small>{r.company} · {r.owner||'Owner required'}</small><h3>{r.name}</h3><strong>{pending?'Needs data':fmt(r.actual)+' '+r.unit}</strong><small>{r.metricSource||'Manual'}{r.metricAsOf?' · As at '+r.metricAsOf:''}</small>{r.metricEvidence&&<p>{r.metricEvidence}</p>}<p>Target {r.direction==='At most'?'≤':'≥'} {fmt(r.targetValue)} {r.unit}</p><span className="status">{pending?'Needs data':good?'On target':'Outside target'}</span><div className="recordactions"><button className="secondary" onClick={()=>open('scorecard',r)}>{r.metricSource&&r.metricSource!=='Manual'?'Edit metric link':'Update actual'}</button><button className="secondary" onClick={()=>newIssue({company:r.company,name:r.name+' scorecard review',owner:r.owner,identified:'Actual '+r.actual+' '+r.unit+'; target '+r.targetValue+' '+r.unit+' for '+bounds.label})}>Raise issue</button></div></article>})}</div>{!metrics.length&&<p className="empty">No metrics for this period. Add your weekly measures or choose a recorded month or quarter.</p>}</>}
{tab==='Rocks'&&<><RockOverview rocks={rocks}/><div className="rocklist">{rocks.map(r=><article key={r.id}><div><small>{r.company} · {r.owner||'Owner required'}</small><h3>{r.name}</h3><p>{r.completionResult||r.notes||'Completion result not recorded'}</p><RockProgress rock={r}/><small>Due {r.due||r.date}</small>{r.blocker&&<p><strong>Blocker:</strong> {r.blocker}</p>}{r.nextAction&&<p><strong>Next action:</strong> {r.nextAction}</p>}</div><div className="eosactions">{status(r,['Open','On track','At risk','Done'])}<button className="secondary" onClick={()=>open('rock',r)}>Edit Rock</button><button className="secondary" onClick={()=>newTodo({company:r.company,rockId:r.id,owner:r.owner,name:'Action for '+r.name})}>Add To do</button><button className="secondary" onClick={()=>newIssue({company:r.company,rockId:r.id,owner:r.owner,name:r.name+' blocker',identified:r.blocker})}>Raise issue</button></div></article>)}</div>{!rocks.length&&<p className="empty">No Rocks for this quarter.</p>}</>}
{tab==='To dos'&&<><div className="sectiontoolbar"><label className="projectfilter">Show<select value={taskFilter} onChange={e=>setTaskFilter(e.target.value)}>{['Open','Done','All'].map(v=><option key={v}>{v}</option>)}</select></label><button className="primary" onClick={()=>newTodo()}>Add To do</button></div><div className="tablebox"><table className="technicaltable"><thead><tr><th>To do</th><th>Company / owner</th><th>Due</th><th>Linked work</th><th>Status</th><th>Actions</th></tr></thead><tbody>{todos.map(r=><tr key={r.id}><td><strong>{r.name}</strong><small>{r.notes}</small></td><td>{r.company}<small>{r.owner}</small></td><td>{r.due}<small>{r.status!=='Done'&&r.due<day()?'Overdue':''}</small></td><td>{[r.rockId,r.issueId,r.meetingId].filter(Boolean).map(id=><small key={id}>{rs.find(x=>x.id===id)?.name||'Record unavailable'}</small>)}</td><td>{status(r,['Open','In progress','Done'])}</td><td><button className="secondary" onClick={()=>open('task',r)}>Edit</button></td></tr>)}</tbody></table>{!todos.length&&<p className="empty">No EOS To dos in this view. EOS actions also appear in Tasks.</p>}</div></>}
{tab==='Issues'&&<><div className="sectiontoolbar"><label className="projectfilter">Show<select value={issueFilter} onChange={e=>setIssueFilter(e.target.value)}>{['Open','Solved','Archived','All'].map(v=><option key={v}>{v}</option>)}</select></label><button className="primary" onClick={()=>newIssue()}>Add issue</button></div><div className="eoscolumns"><section>{issues.map(r=><button className="eoslistlink" key={r.id} aria-pressed={issue?.id===r.id} onClick={()=>setSelectedIssue(r.id)}><strong>{r.name}</strong><span>{r.company} · {r.priority} · {r.status} · {r.owner}</span></button>)}{!issues.length&&<p className="empty">No issues in this view.</p>}</section><section className="eosdetail">{issue?<><small>{issue.company} · {issue.owner}</small><h2>{issue.name}</h2>{status(issue,issueStages)}<h3>Identify</h3><p>{issue.identified||issue.name}</p><h3>Discuss</h3><p>{issue.discussion||'Discussion not recorded'}</p><h3>Solve</h3><p>{issue.resolution||'Solution not recorded'}</p><div className="recordactions"><button className="primary" onClick={()=>open('eos_issue',issue)}>Record IDS outcome</button><button className="secondary" onClick={()=>newTodo({company:issue.company,issueId:issue.id,meetingId:(issue.relatedMeetingIds||[]).includes(selectedMeeting)?selectedMeeting:issue.meetingId,rockId:issue.rockId,owner:issue.owner,name:'Resolve '+issue.name})}>Assign To do</button></div><p className="footnote">Record the discussion and solution before marking Solved. Actions keep their own owners and due dates.</p></>:<p>Select an issue to identify, discuss and solve it.</p>}</section></div></>}
{tab==='L10 meetings'&&<><div className="sectiontoolbar"><button className="primary" disabled={busy||meetingDirty} onClick={()=>setStarting(true)}>Start L10 meeting</button>{meeting&&<label className="projectfilter">Meeting<select aria-label="Select L10 meeting" value={meeting.id} onChange={e=>{if(meetingDirty&&!window.confirm('Discard unsaved meeting notes?'))return;updateDirty(false);setSelectedMeeting(e.target.value)}}>{s.meetings.map(r=><option key={r.id} value={r.id}>{r.company} · {r.date} · {r.name} · {r.status}</option>)}</select></label>}</div>{starting?<StartL10 company={company} previous={meeting} busy={busy} act={act} onDirty={updateDirty} onCancel={()=>{updateDirty(false);setStarting(false)}} onStarted={id=>{updateDirty(false);setStarting(false);setSelectedMeeting(id)}}/>:meeting?<L10Meeting key={meeting.id} meeting={meeting} state={state} open={open} create={create} act={act} busy={busy} onDirtyChange={updateDirty} refresh={refresh} startNext={()=>setStarting(true)}/>:<section className="empty"><h2>Start your first L10 meeting</h2><p>The fixed agenda brings metrics, Rocks, To dos and issues into one meeting.</p><ol className="l10fixedpreview">{l10Agenda.map(a=><li key={a.name}>{a.name}<span>{a.minutes} min</span></li>)}</ol></section>}</>}
</div>;
}
